{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Ergotamine, the closest analogue sharing the ergopeptine cyclol scaffold, has absolute oral bioavailability of only 0.9–3.4% in migraine patients, directly supporting a low-F outcome for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Methysergide, another ergoline amide, has systemic availability of only 13%, supporting that sub-20% oral bioavailability occurs in this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bromerguride, a brominated ergoline without the cyclol peptide, has 29% oral bioavailability, showing that bromine alone does not dictate low F; its lower structural similarity limits its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "LSD, a simpler lysergamide, has 80% oral bioavailability, showing high F is possible in the ergoline class, but the query's bulky cyclol peptide makes this evidence less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue, ergotamine, shares the ergopeptine cyclol core and has absolute oral bioavailability below 5%, strongly outweighing higher-F data from simpler ergolines such as bromerguride and LSD that lack this scaffold. The query's brominated ergopeptine is therefore predicted to have F below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule is available.",
    "Human pharmacokinetic data for this specific brominated ergopeptine are absent.",
    "First-pass metabolism, solubility, and formulation/dose effects for the query are not provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

